894	/** One line for a failed gate: the rejected check ids and their distinct reasons, e.g. "unit, integration — no passing test evidence". */
895	function gateSummary(result: WorkerResult, checks: readonly { id: string; command: string }[]): string {
896	  const reasons = gateReasonsByCheck(result.error?.message, checks)
897	  const keyed = reasons.reasons.filter(reason => reason.check_id !== null)
898	  if (!keyed.length) return result.error?.message ?? 'the gate did not pass'
899	  return `${[...new Set(keyed.map(reason => reason.check_id))].join(', ')} — ${[...new Set(keyed.map(reason => reason.reason))].join('; ')}`
900	}
